// Generic Combat Zone background picker
// Macro type: Script. For Foundry VTT v14 (Scene Levels, DialogV2).

const FOLDER = "worlds/13th-age/scenes/Generic Combat Zones";
const SCENE_UUID = "Scene.mIWrJ2Z6Gx3csDPU";
const COLUMNS = 4;
const MAX_ROWS = COLUMNS;          // rows shown before the gallery scrolls
const MAX_SCREEN_FRACTION = 0.75;  // never let the gallery be taller than this share of the screen
const UPLOAD_POSITION = "right";   // "right" (next to the ⋮ menu) or "left" (before the title)

const { FilePicker } = foundry.applications.apps;
const { DialogV2 } = foundry.applications.api;

const esc = s => String(s)
  .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
  .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
const fileName = path => decodeURIComponent(path.split("/").pop().split("?")[0]);

if (!game.user.isGM) return ui.notifications.warn("Only a GM can change a scene's background.");

const scene = await fromUuid(SCENE_UUID);
if (!scene) return ui.notifications.error(`Scene ${SCENE_UUID} not found.`);

// In v14 the background lives on a Level. Use the scene's initial level,
// falling back to the lowest level if no initial level is set.
const level = scene.levels.get(scene.initialLevel)
  ?? scene.levels.contents.sort((a, b) => (a.elevation.bottom - b.elevation.bottom) || (a.sort - b.sort))[0];
if (!level) return ui.notifications.error(`Scene "${scene.name}" has no levels to set a background on.`);

// Image listing
const imageExts = Object.keys(CONST.IMAGE_FILE_EXTENSIONS).map(e => `.${e}`);
const isImage = p => imageExts.some(ext => p.toLowerCase().split("?")[0].endsWith(ext));
const byName = (a, b) => fileName(a).localeCompare(fileName(b), undefined, { numeric: true });

async function listImages() {
  const result = await FilePicker.implementation.browse("data", FOLDER, { extensions: imageExts });
  return (result.files ?? []).filter(isImage).sort(byName);
}

let files;
try {
  files = await listImages();
} catch (err) {
  return ui.notifications.error(`Could not read folder "${FOLDER}": ${err.message}`);
}

// The dialog strips <style> tags from its content, so the hover and selection
// styles are added to the page head once, and the layout uses inline styles.
document.getElementById("gcz-picker-style")?.remove();
const pageStyle = document.createElement("style");
pageStyle.id = "gcz-picker-style";
pageStyle.textContent = `
  .gcz-dialog .gcz-tile { transition: border-color 0.1s, background 0.1s; }
  .gcz-dialog .gcz-tile:hover { border-color: rgba(255, 255, 255, 0.4) !important; }
  .gcz-dialog .gcz-tile.selected {
    border-color: var(--color-border-highlight, #ff6400) !important;
    background: rgba(255, 100, 0, 0.2) !important;
    box-shadow: 0 0 8px var(--color-shadow-highlight, #ff6400);
  }
  .gcz-dialog .gcz-tile .gcz-check { display: none; }
  .gcz-dialog .gcz-tile.selected .gcz-check { display: flex !important; }
`;
document.head.append(pageStyle);

const STYLE = {
  gallery: `display:grid; grid-template-columns:repeat(${COLUMNS}, minmax(0, 1fr)); gap:10px;
            align-content:start; max-height:65vh; overflow-y:auto; padding:6px;
            width:100%; box-sizing:border-box;`,
  tile: `position:relative; margin:0; padding:4px; cursor:pointer; min-width:0;
         border:2px solid transparent; border-radius:6px; background:rgba(0,0,0,0.15);
         display:flex; flex-direction:column; box-sizing:border-box;`,
  img: `display:block; width:100%; height:auto; max-width:100%; aspect-ratio:16/10;
        object-fit:cover; border:none; border-radius:4px; pointer-events:none;`,
  caption: `margin-top:4px; font-size:12px; text-align:center;
            white-space:nowrap; overflow:hidden; text-overflow:ellipsis;`,
  check: `position:absolute; top:8px; right:8px; width:26px; height:26px; border-radius:50%;
          align-items:center; justify-content:center; font-size:15px; pointer-events:none;
          background:var(--color-border-highlight, #ff6400); color:#fff;
          box-shadow:0 0 4px rgba(0,0,0,0.6);`,
  empty: `grid-column:1 / -1; margin:2em 0; text-align:center; opacity:0.8;`
};

const tileHTML = (path, i) => {
  const name = fileName(path);
  return `
    <div class="gcz-tile" data-index="${i}" title="${esc(name)}" style="${STYLE.tile}">
      <img src="${esc(path)}" loading="lazy" alt="${esc(name)}" style="${STYLE.img}">
      <span class="gcz-check" style="${STYLE.check}"><i class="fa-solid fa-check"></i></span>
      <div class="gcz-caption" style="${STYLE.caption}">${esc(name)}</div>
    </div>`;
};

const styleTile = tile => {
  tile.style.cssText = STYLE.tile;
  tile.querySelector("img").style.cssText = STYLE.img;
  tile.querySelector(".gcz-check").style.cssText = STYLE.check;
  tile.querySelector(".gcz-caption").style.cssText = STYLE.caption;
};

const makeTile = (path, i) => {
  const template = document.createElement("template");
  template.innerHTML = tileHTML(path, i).trim();
  const tile = template.content.firstElementChild;
  styleTile(tile);
  return tile;
};

const content = `
  <div class="gcz-gallery" style="${STYLE.gallery}">
    <p class="gcz-empty" style="${STYLE.empty}">No images in this folder yet. Use the <i class="fa-solid fa-upload"></i> button in the title bar to add some.</p>
    ${files.map(tileHTML).join("")}
  </div>
  <input type="hidden" name="gczSelected" value="">`;

const choice = await DialogV2.wait({
  classes: ["gcz-dialog"],
  window: { title: `${scene.name} (Scene): Choose a Background`, resizable: true },
  position: { width: 900 },
  content,
  rejectClose: false,
  buttons: [
    {
      action: "confirm",
      label: "Confirm",
      icon: "fa-solid fa-check",
      callback: (event, button) => {
        const value = button.form.elements.gczSelected.value;
        return value === "" ? null : { path: files[Number(value)] };
      }
    },
    {
      action: "cancel",
      label: "Cancel",
      icon: "fa-solid fa-xmark",
      default: true
    }
  ],
  render: (event, dialog) => {
    const root = dialog.element;
    const gallery = root.querySelector(".gcz-gallery");
    const emptyMsg = gallery.querySelector(".gcz-empty");
    const input = root.querySelector('input[name="gczSelected"]');
    const confirmBtn = root.querySelector('button[data-action="confirm"]');

    // Re-apply the layout directly on the rendered elements
    gallery.style.cssText = STYLE.gallery;
    emptyMsg.style.cssText = STYLE.empty;
    gallery.querySelectorAll(".gcz-tile").forEach(styleTile);

    const updateEmpty = () => { emptyMsg.style.display = files.length ? "none" : ""; };
    updateEmpty();

    // Selection (one at a time, click again to deselect)
    const select = tile => {
      gallery.querySelectorAll(".gcz-tile.selected").forEach(t => t.classList.remove("selected"));
      if (tile) tile.classList.add("selected");
      input.value = tile ? tile.dataset.index : "";
      confirmBtn.disabled = !tile;
    };
    select(null);

    gallery.addEventListener("click", ev => {
      const tile = ev.target.closest(".gcz-tile");
      if (!tile) return;
      select(tile.classList.contains("selected") ? null : tile);
    });

    // Cap the gallery at MAX_ROWS rows of tiles; further rows scroll
    const fitHeight = () => {
      if (!gallery.isConnected) return;
      const tile = gallery.querySelector(".gcz-tile");
      if (!tile) { gallery.style.maxHeight = ""; return; }
      const gs = getComputedStyle(gallery);
      const gap = parseFloat(gs.rowGap) || 0;
      const pad = (parseFloat(gs.paddingTop) || 0) + (parseFloat(gs.paddingBottom) || 0);
      const rowsHeight = MAX_ROWS * tile.offsetHeight + (MAX_ROWS - 1) * gap + pad;
      const capped = Math.min(Math.ceil(rowsHeight), Math.floor(window.innerHeight * MAX_SCREEN_FRACTION));
      const value = `${capped}px`;
      if (gallery.style.maxHeight !== value) gallery.style.maxHeight = value;
    };
    const fitWindow = () => requestAnimationFrame(() => {
      fitHeight();
      dialog.setPosition({ height: "auto" });
    });
    fitWindow();

    // Tiles change height when the window is resized wider/narrower
    let lastWidth = 0;
    new ResizeObserver(entries => {
      const width = entries[0].contentRect.width;
      if (Math.abs(width - lastWidth) < 1) return;
      lastWidth = width;
      fitHeight();
    }).observe(gallery);

    // Upload button in the window header (doesn't close the window)
    const fileInput = document.createElement("input");
    fileInput.type = "file";
    fileInput.multiple = true;
    fileInput.accept = imageExts.join(",");
    fileInput.hidden = true;
    root.append(fileInput);

    const header = dialog.window?.header ?? root.querySelector(".window-header");
    const uploadBtn = document.createElement("button");
    uploadBtn.type = "button";
    uploadBtn.className = "header-control icon fa-solid fa-upload";
    uploadBtn.dataset.tooltip = "Upload images";
    uploadBtn.setAttribute("aria-label", "Upload images");

    if (UPLOAD_POSITION === "left") {
      const title = header.querySelector(".window-title");
      header.insertBefore(uploadBtn, title);
      uploadBtn.style.marginRight = "6px";
    } else {
      const anchor = header.querySelector('[data-action="toggleControls"]')
        ?? header.querySelector('[data-action="close"]');
      header.insertBefore(uploadBtn, anchor ?? null);
    }

    // Stop the header's drag handler from treating the click as a window drag
    uploadBtn.addEventListener("pointerdown", ev => ev.stopPropagation());
    uploadBtn.addEventListener("click", ev => {
      ev.preventDefault();
      ev.stopPropagation();
      fileInput.click();
    });

    fileInput.addEventListener("change", async () => {
      const picked = Array.from(fileInput.files).filter(f => isImage(f.name));
      fileInput.value = "";
      if (!picked.length) return ui.notifications.warn("No image files were selected.");

      uploadBtn.disabled = true;
      try {
        for (const file of picked) {
          await FilePicker.implementation.upload("data", FOLDER, file, {}, { notify: true });
        }

        // Re-read the folder and add anything new to the gallery
        const latest = await listImages();
        const known = new Map(files.map((p, i) => [fileName(p), i]));
        const pickedNames = new Set(picked.map(f => f.name));
        const added = [];
        let replaced = null;

        for (const path of latest) {
          const name = fileName(path);
          if (known.has(name)) {
            // Same filename uploaded again: refresh its preview
            if (pickedNames.has(name)) {
              const tile = gallery.querySelector(`.gcz-tile[data-index="${known.get(name)}"]`);
              if (tile) {
                tile.querySelector("img").src = `${files[known.get(name)]}?t=${Date.now()}`;
                replaced = tile;
              }
            }
            continue;
          }
          files.push(path);
          const tile = makeTile(path, files.length - 1);
          const next = [...gallery.querySelectorAll(".gcz-tile")]
            .find(t => byName(files[Number(t.dataset.index)], path) > 0);
          gallery.insertBefore(tile, next ?? null);
          added.push(tile);
        }

        updateEmpty();
        fitWindow();

        // Select the most recently uploaded image and scroll to it
        const target = added.at(-1) ?? replaced;
        if (target) {
          select(target);
          target.scrollIntoView({ block: "nearest", behavior: "smooth" });
        }
      } catch (err) {
        ui.notifications.error(`Upload failed: ${err.message}`);
      } finally {
        uploadBtn.disabled = false;
      }
    });
  }
});

// Closing the window or pressing Cancel does nothing
if (!choice || typeof choice !== "object" || !choice.path) return;

await level.update({ "background.src": choice.path });

// Regenerate the scene's thumbnail, same as "Generate Thumbnail Image" in the Scenes sidebar
try {
  const data = await scene.createThumbnail({ level: level.id });
  await scene.update({ thumb: data.thumb }, { diff: false });
} catch (err) {
  ui.notifications.warn(`Background changed, but the thumbnail could not be generated: ${err.message}`);
}

ui.notifications.info(`"${scene.name}" background set to ${fileName(choice.path)}.`);
